import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry alexnet_conv1(
    .param .u64 param_in,
    .param .u64 param_w,
    .param .u64 param_b,
    .param .u64 param_out,
    .param .u32 param_total
)
{
    .reg .pred %p<16>;
    .reg .b32 %r<64>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<8>;

    ld.param.u64 %rd1, [param_in];
    ld.param.u64 %rd2, [param_w];
    ld.param.u64 %rd3, [param_b];
    ld.param.u64 %rd4, [param_out];
    ld.param.u32 %r1, [param_total];

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;

    setp.ge.u32 %p1, %r5, %r1;
    @%p1 ret;

    // decode tid -> (b, oc, oh, ow) for output (B, 96, 55, 55)
    mov.u32 %r6, 55;
    div.u32 %r7, %r5, %r6;
    rem.u32 %r8, %r5, %r6;      // ow
    div.u32 %r9, %r7, %r6;
    rem.u32 %r10, %r7, %r6;     // oh
    mov.u32 %r11, 96;
    div.u32 %r12, %r9, %r11;    // b
    rem.u32 %r13, %r9, %r11;    // oc

    // input batch base = b * 3 * 224 * 224
    mov.u32 %r14, 150528;
    mul.lo.u32 %r15, %r12, %r14;
    // weight oc base = oc * 3 * 11 * 11
    mov.u32 %r16, 363;
    mul.lo.u32 %r17, %r13, %r16;
    // oy0 = oh * 4 - 2 ; ox0 = ow * 4 - 2
    shl.b32 %r18, %r10, 2;
    sub.s32 %r19, %r18, 2;
    shl.b32 %r20, %r8, 2;
    sub.s32 %r21, %r20, 2;

    mov.f32 %f1, 0f00000000;

    mov.u32 %r22, 0;            // ic
$ic_loop:
    setp.lt.u32 %p2, %r22, 3;
    @!%p2 bra $conv_done;
    mov.u32 %r23, 50176;
    mul.lo.u32 %r24, %r22, %r23;
    add.u32 %r25, %r15, %r24;   // input base for (b, ic)
    mov.u32 %r26, 121;
    mul.lo.u32 %r27, %r22, %r26;
    add.u32 %r28, %r17, %r27;   // weight base for (oc, ic)

    mov.u32 %r29, 0;            // ky
$ky_loop:
    setp.lt.u32 %p3, %r29, 11;
    @!%p3 bra $ky_done;
    add.s32 %r30, %r19, %r29;   // iy
    setp.ge.s32 %p5, %r30, 0;
    setp.lt.s32 %p6, %r30, 224;
    and.pred %p7, %p5, %p6;     // y valid
    mov.u32 %r31, 224;
    mul.lo.u32 %r32, %r30, %r31;
    add.u32 %r33, %r25, %r32;   // input row base (valid only if y valid)
    mov.u32 %r34, 11;
    mul.lo.u32 %r35, %r29, %r34;
    add.u32 %r36, %r28, %r35;   // weight row base

    mov.u32 %r37, 0;            // kx
$kx_loop:
    setp.lt.u32 %p4, %r37, 11;
    @!%p4 bra $kx_done;
    add.s32 %r38, %r21, %r37;   // ix
    setp.ge.s32 %p5, %r38, 0;
    setp.lt.s32 %p6, %r38, 224;
    and.pred %p8, %p5, %p6;
    and.pred %p8, %p8, %p7;     // x valid && y valid
    @!%p8 bra $skip_tap;
    add.u32 %r39, %r33, %r38;   // input element offset
    add.u32 %r40, %r36, %r37;   // weight element offset
    cvt.u64.u32 %rd5, %r39;
    shl.b64 %rd6, %rd5, 2;
    add.u64 %rd7, %rd1, %rd6;
    cvt.u64.u32 %rd8, %r40;
    shl.b64 %rd9, %rd8, 2;
    add.u64 %rd10, %rd2, %rd9;
    ld.global.f32 %f2, [%rd7];
    ld.global.f32 %f3, [%rd10];
    fma.rn.f32 %f1, %f2, %f3, %f1;
$skip_tap:
    add.u32 %r37, %r37, 1;
    bra $kx_loop;
$kx_done:
    add.u32 %r29, %r29, 1;
    bra $ky_loop;
$ky_done:
    add.u32 %r22, %r22, 1;
    bra $ic_loop;
$conv_done:
    // add bias[oc]
    cvt.u64.u32 %rd11, %r13;
    shl.b64 %rd12, %rd11, 2;
    add.u64 %rd13, %rd3, %rd12;
    ld.global.f32 %f4, [%rd13];
    add.f32 %f1, %f1, %f4;
    // store out[tid]
    cvt.u64.u32 %rd14, %r5;
    shl.b64 %rd15, %rd14, 2;
    add.u64 %rd16, %rd4, %rd15;
    st.global.f32 [%rd16], %f1;
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("alexnet_conv1")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        x = x.contiguous()
        weight = self.conv1.weight.contiguous()
        bias = self.conv1.bias.contiguous()
        batch = x.shape[0]
        out = torch.empty((batch, 96, 55, 55), dtype=x.dtype, device=x.device)
        total = out.numel()
        block = 256
        grid = (total + block - 1) // block
        module = _get_ptx_module()
        module.launch(
            "alexnet_conv1",
            grid=(grid, 1, 1),
            block=(block, 1, 1),
            arguments=[x, weight, bias, out, i32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

